use anyhow::{Result,ensure};
use sarv_quote::{domain::State,store::{Store,backup_state},export};
use std::{fs,path::PathBuf};
fn main()->Result<()> {let args:Vec<_>=std::env::args().collect();let dir=PathBuf::from(&args[1]);fs::create_dir_all(&dir)?;let envelope:serde_json::Value=serde_json::from_slice(&fs::read(&args[2])?)?;let prior:State=serde_json::from_value(envelope["state"].clone())?;ensure!(prior.schema==3&&prior.quotes.len()==3&&prior.accounting.journals.len()==3,"actual retained M2 fixture");prior.validate()?;let csv=prior.quotes.iter().map(export::csv_bytes).collect::<Result<Vec<_>>>()?;
 let db=rusqlite::Connection::open(dir.join("sarv.sqlite3"))?;db.execute_batch("CREATE TABLE state(id INTEGER PRIMARY KEY CHECK(id=1),generation INTEGER NOT NULL,payload TEXT NOT NULL)")?;db.execute("INSERT INTO state VALUES(1,27,?1)",[serde_json::to_string(&prior)?])?;drop(db);
 let store=Store::open(&dir)?;ensure!(store.state.schema==4&&store.local_generation()==28,"actual3→4 onegeneration");let mut expected=serde_json::to_value(&prior)?;expected["schema"]=4.into();ensure!(serde_json::to_value(&store.state)?==expected,"quote/history/account/date exact preserve");ensure!(csv==store.state.quotes.iter().map(export::csv_bytes).collect::<Result<Vec<_>>>()?,"CSV bytes preserve");
 let recoveries=fs::read_dir(&dir)?.map(|x|x.unwrap().path()).filter(|p|p.file_name().unwrap().to_string_lossy().starts_with("before-schema4-")).collect::<Vec<_>>();ensure!(recoveries.len()==1,"one recovery");let recovery:serde_json::Value=serde_json::from_slice(&fs::read(&recoveries[0])?)?;ensure!(recovery["format"]=="sarv-accounting-backup-v3"&&recovery["state"]==envelope["state"],"exact verified preupgrade schema3 recovery");ensure!(serde_json::to_value(Store::restore_preview(&recoveries[0])?)?==expected,"verified recovery reconstruct");store.backup(&dir.join("new-v4.json"))?;let mut fresh=Store::open(&dir.join("fresh"))?;fresh.restore(Store::restore_preview(&recoveries[0])?)?;ensure!(serde_json::to_value(&fresh.state)?==expected,"fresh restored books exact");
 export::pdf(&store.state.quotes[0],&dir.join("historical-quote.pdf"))?;drop(store);let reopened=Store::open(&dir)?;ensure!(reopened.local_generation()==28&&serde_json::to_value(&reopened.state)?==expected,"idempotent reopen");backup_state(&prior,&dir.join("independent-old-v3-backup.json"))?;
 let db=rusqlite::Connection::open(dir.join("sarv.sqlite3"))?;let integrity:String=db.query_row("PRAGMA integrity_check",[],|r|r.get(0))?;ensure!(integrity=="ok","integrity");println!("PASS independent actualschema3→4, generation27→28; all3quotes/3journals and CSV byte-exact; original recovery v3 exact; v4 backup; fresh restore/reopen exact; SQLite integrityok");Ok(())}
